// Runs ONCE PER ITEM. It used to run once for all of them and read `$json`,
// which is only the FIRST item -- so of sixteen scraped pages exactly one was
// ever parsed and the other fifteen were dropped without a trace.
//
// -- 01 Sep 2026 - THE COMPARISON WAS NEVER A COMPARISON -----------------------
// Two defects made every row on the Competitors screen unfalsifiable.
//
// 1. The row stored OUR model string in `model` and nothing from the other
//    page, so the screen's "match" compared our string to itself. It agreed by
//    construction, and the match-quality warning could never fire. The listing's
//    own title now goes to `listingTitle`, and `model` is documented as the
//    join key it always was.
//
// 2. The price was Math.min of EVERY AED figure over 20,000 anywhere in the
//    page's JSON-LD -- no year, trim, mileage or condition constraint. Our used
//    2.7 VXR at 152,000 was compared against toyota.ae's cheapest NEW BASE
//    Fortuner at 128,900 and the screen printed "+AED 23,100 - 17.9% above
//    theirs" in red. A rep repricing on that is matching a different car.
//    Offers now carry their own name and condition, the offer is chosen by how
//    well it matches our unit, and the row records WHICH offer won and how
//    confident that match is. When nothing ties an offer to our car the row is
//    still written -- a cheap page is worth knowing about -- but it is stamped
//    `weak`, and the screen is expected to refuse to draw a conclusion from it.
const response = $json;

let original = {};
try { original = $('Build Apify Query').item.json || {}; } catch (e) { original = {}; }

let apifyItem = {};
try { apifyItem = $('Apify - Search Competitor Price').item.json || {}; } catch (e) { apifyItem = {}; }

let parsed = { price: null };
try { parsed = JSON.parse(response.choices?.[0]?.message?.content || '{}'); } catch (e) { /* keep default */ }

const meta   = apifyItem.metadata || {};
const jsonLd = meta.jsonLd || {};
const offers = jsonLd.offers || {};

/* A dealership LISTING page publishes an ItemList, not a single offer, so the
   prices live at @graph.itemListElement[].item.offers.price. Walk the whole
   structure -- but carry each price's own name and condition out with it, so
   the choice below can be about the right car instead of the lowest number. */
function collectOffers(node, depth, inheritedName, inheritedCondition) {
  if (!node || depth > 8) return [];
  if (Array.isArray(node)) {
    return node.flatMap(v => collectOffers(v, depth + 1, inheritedName, inheritedCondition));
  }
  if (typeof node !== 'object') return [];

  const name = (typeof node.name === 'string' && node.name.trim()) ? node.name.trim() : inheritedName;
  let condition = inheritedCondition;
  const rawCond = node.itemCondition || node.condition;
  if (typeof rawCond === 'string') {
    if (/used|second|pre-?owned/i.test(rawCond)) condition = 'used';
    else if (/new/i.test(rawCond)) condition = 'new';
  }

  let found = [];
  const cur = node.priceCurrency ? String(node.priceCurrency).toUpperCase() : null;
  if (node.price !== undefined && (!cur || cur === 'AED')) {
    const n = Number(String(node.price).replace(/[^0-9.]/g, ''));
    // Under 20k is a deposit, an accessory or a monthly instalment, not a car.
    if (Number.isFinite(n) && n >= 20000) found.push({ price: n, name: name || null, condition: condition || null });
  }
  for (const k of Object.keys(node)) {
    found = found.concat(collectOffers(node[k], depth + 1, name, condition));
  }
  return found;
}

const yearOf  = s => { const m = String(s || '').match(/\b(19|20)\d{2}\b/); return m ? m[0] : null; };
const tokens  = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(t => t.length > 1);

const ourModel = original.model ?? null;
const ourYear  = yearOf(ourModel);
const ourToks  = tokens(ourModel).filter(t => !/^(19|20)\d{2}$/.test(t));

const ldOffers = collectOffers(jsonLd, 0, null, null);

/* Rank every offer against OUR unit rather than against zero. An offer that
   names our model year is the only kind that can support a price claim; an
   offer that matches the model name but not the year is worth showing with the
   caveat; anything else is the page's cheapest number and proves nothing. */
function rate(offer) {
  const oToks = tokens(offer.name);
  if (!offer.name || !oToks.length) return { q: 'weak', hits: 0 };
  const hits = ourToks.filter(t => oToks.includes(t)).length;
  const oYear = yearOf(offer.name);
  if (ourYear && oYear && oYear === ourYear && hits > 0) return { q: 'exact_year', hits };
  if (ourYear && oYear && oYear !== ourYear)             return { q: 'weak', hits };
  if (hits >= Math.max(1, Math.ceil(ourToks.length / 2))) return { q: 'model_only', hits };
  return { q: 'weak', hits };
}

const RANK = { exact_year: 3, model_only: 2, weak: 1 };
let chosen = null, chosenRate = null;
for (const o of ldOffers) {
  const r = rate(o);
  if (!chosen) { chosen = o; chosenRate = r; continue; }
  // Best match first; among equally good matches, the lowest price -- that was
  // the original intent and is right once "equally good" actually means it.
  if (RANK[r.q] > RANK[chosenRate.q] ||
     (RANK[r.q] === RANK[chosenRate.q] && r.hits > chosenRate.hits) ||
     (RANK[r.q] === RANK[chosenRate.q] && r.hits === chosenRate.hits && o.price < chosen.price)) {
    chosen = o; chosenRate = r;
  }
}

const ldPrice    = chosen ? chosen.price : null;
const modelPrice = (typeof parsed.price === 'number' && parsed.price > 0) ? parsed.price : null;
const competitorPrice = ldPrice !== null ? ldPrice : modelPrice;
const priceFrom = ldPrice !== null ? 'schema.org JSON-LD' : 'model extraction';
const localPrice = original.localPrice ?? null;

/* The model extraction path is asked for "the lowest advertised price" with no
   way to say what it was for, so it can never be better than weak. */
let matchQuality = ldPrice !== null ? chosenRate.q : (competitorPrice !== null ? 'weak' : null);
let matchNote = null;
if (matchQuality === 'exact_year') {
  matchNote = 'The chosen offer names our model year (' + ourYear + ').';
} else if (matchQuality === 'model_only') {
  matchNote = 'Model name matched but the offer states no year, so trim and year are unconfirmed.';
} else if (matchQuality === 'weak') {
  matchNote = ldPrice !== null
