const jsonLd = meta.jsonLd || {};
const offers = jsonLd.offers || {};

/* A dealership LISTING page publishes an ItemList, not a single offer, so the
   prices live at @graph.itemListElement[].item.offers.price. Walk the whole
   structure -- but carry each price's own name and condition out with it, so
   the choice below can be about the right car instead of the lowest number. */
function collectOffers(node, depth, inheritedName, inheritedCondition) {
  if (!node || depth > 8) return [];
  if (Array.isArray(node)) {
    return node.flatMap(v => collectOffers(v, depth + 1, inheritedName, inheritedCondition));
  }
  if (typeof node !== 'object') return [];

  const name = (typeof node.name === 'string' && node.name.trim()) ? node.name.trim() : inheritedName;
  let condition = inheritedCondition;
  const rawCond = node.itemCondition || node.condition;
  if (typeof rawCond === 'string') {
    if (/used|second|pre-?owned/i.test(rawCond)) condition = 'used';
    else if (/new/i.test(rawCond)) condition = 'new';
  }

  let found = [];
  const cur = node.priceCurrency ? String(node.priceCurrency).toUpperCase() : null;
  if (node.price !== undefined && (!cur || cur === 'AED')) {
    const n = Number(String(node.price).replace(/[^0-9.]/g, ''));
    // Under 20k is a deposit, an accessory or a monthly instalment, not a car.
    if (Number.isFinite(n) && n >= 20000) found.push({ price: n, name: name || null, condition: condition || null });
  }
  for (const k of Object.keys(node)) {
    found = found.concat(collectOffers(node[k], depth + 1, name, condition));
  }
  return found;
}

const yearOf  = s => { const m = String(s || '').match(/\b(19|20)\d{2}\b/); return m ? m[0] : null; };
const tokens  = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(t => t.length > 1);

const ourModel = original.model ?? null;
const ourYear  = yearOf(ourModel);
const ourToks  = tokens(ourModel).filter(t => !/^(19|20)\d{2}$/.test(t));

const ldOffers = collectOffers(jsonLd, 0, null, null);

/* Rank every offer against OUR unit rather than against zero. An offer that
   names our model year is the only kind that can support a price claim; an
   offer that matches the model name but not the year is worth showing with the
   caveat; anything else is the page's cheapest number and proves nothing. */
function rate(offer) {
  const oToks = tokens(offer.name);
  if (!offer.name || !oToks.length) return { q: 'weak', hits: 0 };
  const hits = ourToks.filter(t => oToks.includes(t)).length;
  const oYear = yearOf(offer.name);
  if (ourYear && oYear && oYear === ourYear && hits > 0) return { q: 'exact_year', hits };
  if (ourYear && oYear && oYear !== ourYear)             return { q: 'weak', hits };
  if (hits >= Math.max(1, Math.ceil(ourToks.length / 2))) return { q: 'model_only', hits };
  return { q: 'weak', hits };
}

const RANK = { exact_year: 3, model_only: 2, weak: 1 };
let chosen = null, chosenRate = null;
for (const o of ldOffers) {
  const r = rate(o);
  if (!chosen) { chosen = o; chosenRate = r; continue; }
  // Best match first; among equally good matches, the lowest price -- that was
  // the original intent and is right once "equally good" actually means it.
  if (RANK[r.q] > RANK[chosenRate.q] ||
     (RANK[r.q] === RANK[chosenRate.q] && r.hits > chosenRate.hits) ||
     (RANK[r.q] === RANK[chosenRate.q] && r.hits === chosenRate.hits && o.price < chosen.price)) {
    chosen = o; chosenRate = r;
  }
}

const ldPrice    = chosen ? chosen.price : null;
const modelPrice = (typeof parsed.price === 'number' && parsed.price > 0) ? parsed.price : null;
const competitorPrice = ldPrice !== null ? ldPrice : modelPrice;
const priceFrom = ldPrice !== null ? 'schema.org JSON-LD' : 'model extraction';
const localPrice = original.localPrice ?? null;

/* The model extraction path is asked for "the lowest advertised price" with no
   way to say what it was for, so it can never be better than weak. */
let matchQuality = ldPrice !== null ? chosenRate.q : (competitorPrice !== null ? 'weak' : null);
let matchNote = null;
if (matchQuality === 'exact_year') {
  matchNote = 'The chosen offer names our model year (' + ourYear + ').';
} else if (matchQuality === 'model_only') {
  matchNote = 'Model name matched but the offer states no year, so trim and year are unconfirmed.';
} else if (matchQuality === 'weak') {
  matchNote = ldPrice !== null
    ? 'Nothing on the page ties this price to our unit; it is the best available offer on a page about this model.'
    : 'Price came from the language model asked for the lowest advertised figure, which cannot say what it was for.';
}

/* The source is not a judgement call: the page's own hostname always exists.
   Asking the model to name the site from the first 6000 characters of markdown
   is what produced the null sources the guard below kept rejecting. */
let hostSource = null;
try {
  const u = String(meta.url || meta.canonicalUrl || '');
  if (u) hostSource = new URL(u).hostname.replace(/^www\./, '');
} catch (e) { /* not parseable */ }
const ldSeller = (offers.seller && typeof offers.seller.name === 'string') ? offers.seller.name.trim() : '';
const modelSource = typeof parsed.source === 'string' ? parsed.source.trim() : '';

/* A hostname is not a dealership. toyota.ae is the manufacturer quoting new-car
   list prices; dubizzle is a marketplace of other people's ads. Both were
   stored under a column called `competitor` and read on the floor as rival
   showrooms. Classify what we can and admit the rest. */
const OEM = /^(toyota|lexus|nissan|infiniti|honda|hyundai|kia|mitsubishi|ford|chevrolet|gmc|jeep|dodge|ram|bmw|mercedes-benz|mercedes|audi|volkswagen|vw|porsche|landrover|land-rover|jaguar|volvo|mazda|suzuki|renault|peugeot|citroen|skoda|seat|mini|bentley|rollsroyce|ferrari|lamborghini|maserati|tesla|byd|mg|chery|haval|geely|changan|jetour|gac)\./i;
const MARKETPLACE = /(dubizzle|yallamotor|carswitch|opensooq|cars24|kavak|autotrader|dubicars|motory|hatla2ee|carsome|sellanycar|copart|olx)\./i;
let sourceKind = 'unknown';
if (hostSource) {
  if (OEM.test(hostSource)) sourceKind = 'oem';
  else if (MARKETPLACE.test(hostSource)) sourceKind = 'marketplace';
  else sourceKind = 'dealer';
}

/* The listing's own words about what it is selling. This is the field that
   makes a match falsifiable; without it the screen was comparing our string to
   our string. */
const listingTitle = (typeof jsonLd.name === 'string' && jsonLd.name.trim())
  ? jsonLd.name.trim()
  : ((typeof meta.title === 'string' && meta.title.trim()) ? meta.title.trim().slice(0, 200) : null);

/* A bot-detection interstitial is a scrape failure wearing a dealership's
   clothes -- "Pardon Our Interruption" once entered `competitors` as a rival. */
const BLOCK_PAGE = /pardon our interruption|just a moment|access denied|are you a robot|captcha|cloudflare|attention required|verify you are human|enable javascript|403 forbidden|too many requests|unusual traffic/i;
const NOT_A_NAME = /^(null|undefined|none|n\/?a|unknown|-{1,}|\s*)$/i;

/* A hostname always exists, which is exactly the trap: a Google results page
   has one too. The first real run filed `google.com` as a rival dealership
   quoting 105,200 for a Fortuner -- a search page's own snippet, not an offer
   anyone will honour. */
const NOT_A_SELLER = /^(www\.)?(google|bing|duckduckgo|yahoo|search|youtube|facebook|instagram|twitter|x|linkedin|tiktok|pinterest|reddit|quora|wikipedia|wikiwand|medium|blogspot|wordpress|tripadvisor|amazon|aliexpress|ebay)\./i;

const raw = ldSeller || hostSource || modelSource;
let source = raw;
let skipReason = null;

if (!raw)                      skipReason = 'the page carried no identifiable source';
else if (NOT_A_SELLER.test(raw + '.')) skipReason = '"' + raw + '" is a search or social site, not a seller';
else if (NOT_A_NAME.test(raw)) skipReason = 'the source was the placeholder "' + raw + '"';
else if (BLOCK_PAGE.test(raw)) skipReason = 'the page was a bot-detection interstitial ("' + raw.slice(0, 60) + '")';
else if (raw.length > 80)      skipReason = 'the source read as prose, not a seller name';
if (skipReason) source = null;

/* No price is not intel either: a row with a null price cannot support an
   undercut claim, and every one written so far was noise in the table the
   dashboard reads. */
if (competitorPrice === null && !skipReason) skipReason = 'no price could be extracted from the page';

return { json: {
  id: original.id ?? null,
  model: original.model ?? null,
  listingTitle: listingTitle,
  pageUrl: meta.url || null,
  localPrice: localPrice,
  competitorPrice: competitorPrice,
  priceDiff: (competitorPrice !== null && localPrice !== null) ? (competitorPrice - localPrice) : null,
  competitorSource: source,
  sourceHost: hostSource,
  sourceKind: sourceKind,
  offerName: chosen ? chosen.name : null,
  offerCondition: chosen ? chosen.condition : null,
  matchQuality: matchQuality,
  matchNote: matchNote,
  offersSeen: ldOffers.length,
  currency: parsed.currency || 'AED',
  daysInStock: original.daysInStock ?? 0,
  priceFrom: priceFrom,
  usable: !skipReason,
  skipReason: skipReason,
} };

// Verify every node whose success this audit row is about to claim.
// This edge is the TRUE branch of 'Is This Real Intel?', so the intel row was
// just written here and both this node and its claim always run together.
// NOTE: 'Update Prices in Supabase' is NOT claimed. It is orphaned - nothing
// connects into 'Should Update Price?', so that whole sub-branch never runs and
// $('Update Prices in Supabase') would THROW.
const CLAIMED = [
  { node: 'Log Competitor Intel', what: 'competitors intel row', critical: true },
];

function check(c) {
  let it;
  try { it = $(c.node).item; }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!it) return { ...c, ok: false, why: 'node produced no items' };
  const j = it.json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results = CLAIMED.map(check);
const dropped = results.filter(r => !r.ok);
const fatal   = dropped.filter(r => r.critical);

const status = fatal.length   ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

const base = $json;

// When the insert swallows, its output item is the error rather than the stored
// row, so `model` disappears and the audit summary degrades to 'a unit'. Carry
// the model forward from the parse step so the row still names the vehicle.
let p = {};
try { p = $('Parse AI Price').item.json || {}; } catch (e) { p = {}; }

return { json: {
  ...base,
  model: (base.model !== undefined && base.model !== null) ? base.model : (p.model || null),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' - ' + r.why),
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified',
  },
} };
